noncomputable def VTask.banana : {α : Type u_1} -> {β : Type u_2} -> (u v : α) -> (edgeSet : Set β) -> Graph α β :=
fun u v edgeSet =>
let vertexSet := {u, v}
let edgeRelation := λ e => match e with | _ => false
let edgeList := filter (λ e => e ∈ edgeSet) (list.repeat (u, v) (card edgeSet))
Graph.ofVertexSetAndEdges vertexSet edgeRelation edgeList
